<?php declare(strict_types=1); $items=\Conquer\Admin\ItemPresentation::catalog(); ?>
<section class="card catalog-page">
<div class="toolbar"><label>Gegenstand suchen<input type="search" data-catalog-search placeholder="Name, Beschreibung oder Nummer …"></label><label>Kategorie<select data-catalog-category><option value="">Alle Kategorien</option><?php foreach(\Conquer\Admin\ItemPresentation::CATEGORIES as $key=>$label): ?><option value="<?= ah($key) ?>"><?= ah($label) ?></option><?php endforeach ?></select></label><label>Seltenheit<select data-catalog-rarity><option value="">Alle Seltenheiten</option><?php foreach(\Conquer\Admin\ItemPresentation::GRADES as $key=>$label): ?><option value="<?= ah($key) ?>"><?= ah($label) ?></option><?php endforeach ?></select></label></div>
<div class="split"><p data-catalog-count aria-live="polite"><?= count($items) ?> Gegenstände</p><a href="<?= APP_BASE ?>/admin/rewards">Drops bearbeiten →</a></div>
<div class="item-catalog-grid">
